    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"النقطة على المستقيم","math":"<span dir=\"ltr\" class=\"expr\">A ∈ (AC)</span>"},{"quoi":"المسقط العمودي","math":"مسقط <span dir=\"ltr\" class=\"expr pt\">A</span> على <span dir=\"ltr\" class=\"expr\">(AC)</span> هو <span dir=\"ltr\" class=\"expr pt\">A</span> نفسها"},{"quoi":"القاعدة","math":"إذا كانت النقطة تنتمي إلى المستقيم فإنّ بعدها عنه يساوي 0"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">d(A</span> ، <span dir=\"ltr\" class=\"expr\">(AC)) = 0</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"المسقط العمودي","math":"<span dir=\"ltr\" class=\"expr pt\">B</span> هو المسقط العمودي لـ <span dir=\"ltr\" class=\"expr pt\">A</span> على <span dir=\"ltr\" class=\"expr\">(BC)</span>"},{"quoi":"القاعدة","math":"بعد نقطة عن مستقيم هو طول القطعة التي تصلها بمسقطها العمودي عليه"},{"quoi":"نقرأ الطول","math":"<span dir=\"ltr\" class=\"expr\">AB = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">d(A</span> ، <span dir=\"ltr\" class=\"expr\">(BC)) = 3</span> صم"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"المسقط العمودي","math":"<span dir=\"ltr\" class=\"expr pt\">C</span> هو المسقط العمودي لـ <span dir=\"ltr\" class=\"expr pt\">D</span> على <span dir=\"ltr\" class=\"expr\">(BC)</span>"},{"quoi":"القاعدة","math":"بعد نقطة عن مستقيم هو طول القطعة التي تصلها بمسقطها العمودي عليه"},{"quoi":"نقرأ الطول","math":"<span dir=\"ltr\" class=\"expr\">DC = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">d(D</span> ، <span dir=\"ltr\" class=\"expr\">(BC)) = 6</span> صم"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"المسقط العمودي","math":"<span dir=\"ltr\" class=\"expr pt\">A</span> هو المسقط العمودي لـ <span dir=\"ltr\" class=\"expr pt\">C</span> على <span dir=\"ltr\" class=\"expr\">(AB)</span>"},{"quoi":"القاعدة","math":"بعد نقطة عن مستقيم هو طول القطعة التي تصلها بمسقطها العمودي عليه"},{"quoi":"نقرأ الطول","math":"<span dir=\"ltr\" class=\"expr\">CA = 9</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">d(C</span> ، <span dir=\"ltr\" class=\"expr\">(AB)) = 9</span> صم"}],
    indice: "أنزل العمود من النقطة على المستقيم، ثمّ اقرأ الطول",
